describe('Table Sorting by Column Headers', () => {
  beforeEach(() => {
    cy.visit('/table');
    cy.get('table').should('be.visible');
  });

  it('should sort table in ascending order when clicking a column header', () => {
    // Get initial data from the first column
    cy.get('table tbody tr td:first-child').then(($cells) => {
      const initialValues = Array.from($cells).map(el => el.textContent.trim());

      // Click the first column header to sort
      cy.get('table thead th:first-child').click();

      // Verify the data is sorted in ascending order
      cy.get('table tbody tr td:first-child').then(($sortedCells) => {
        const sortedValues = Array.from($sortedCells).map(el => el.textContent.trim());
        const expectedSorted = [...initialValues].sort();
        expect(sortedValues).to.deep.equal(expectedSorted);
      });
    });
  });

  it('should sort table in descending order when clicking column header twice', () => {
    // Get initial data
    cy.get('table tbody tr td:nth-child(2)').then(($cells) => {
      const initialValues = Array.from($cells).map(el => el.textContent.trim());

      // Click column header twice to toggle to descending
      cy.get('table thead th:nth-child(2)').click();
      cy.get('table thead th:nth-child(2)').click();

      // Verify the data is sorted in descending order
      cy.get('table tbody tr td:nth-child(2)').then(($sortedCells) => {
        const sortedValues = Array.from($sortedCells).map(el => el.textContent.trim());
        const expectedSorted = [...initialValues].sort().reverse();
        expect(sortedValues).to.deep.equal(expectedSorted);
      });
    });
  });

  it('should display sort indicator on the active column header', () => {
    // Click a column header
    cy.get('table thead th:nth-child(3)').click();

    // Verify the sort indicator is visible on the clicked header
    cy.get('table thead th:nth-child(3)').should('have.class', 'sorted');

    // Verify other headers do not have the sorted class
    cy.get('table thead th:nth-child(1)').should('not.have.class', 'sorted');
    cy.get('table thead th:nth-child(2)').should('not.have.class', 'sorted');
  });

  it('should handle sorting with numeric values correctly', () => {
    // Click the numeric column header
    cy.get('table thead th').contains('Price').click();

    // Get sorted numeric values
    cy.get('table tbody tr').then(($rows) => {
      const values = Array.from($rows).map(row => 
        parseFloat(row.querySelector('td:nth-child(4)').textContent.trim())
      );

      // Verify values are in ascending numeric order
      for (let i = 0; i < values.length - 1; i++) {
        expect(values[i]).to.be.lte(values[i + 1]);
      }
    });
  });

  it('should maintain table data integrity after sorting', () => {
    // Get the first row data before sorting
    cy.get('table tbody tr:first-child').then(($row) => {
      const rowData = Array.from($row.find('td')).map(el => el.textContent.trim());

      // Click to sort
      cy.get('table thead th:first-child').click();

      // Verify the row data is still intact (all cells in the row moved together)
      cy.get('table tbody tr').then(($rows) => {
        const foundRow = Array.from($rows).find(row => {
          const cells = Array.from(row.querySelectorAll('td')).map(el => el.textContent.trim());
          return cells.join('') === rowData.join('');
        });
        expect(foundRow).to.exist;
      });
    });
  });

  it('should handle empty table gracefully', () => {
    // Navigate to empty table
    cy.visit('/table-empty');

    // Click column header on empty table
    cy.get('table thead th:first-child').click();

    // Verify no errors occur and table remains visible
    cy.get('table').should('be.visible');
    cy.get('table tbody tr').should('have.length', 0);
  });
});
